    private final String dbPass = requireEnv("MONGO_INITDB_ROOT_PASSWORD");
    private final String dbName = requireEnv("MONGO_DB");
    private final String dbPort = requireEnv("MONGO_PORT");
    private final String dbHost = requireEnv("DBHOST");
    private final String authDb = envOrDefault("MONGO_AUTH_DB", "admin");

